mapper.select:
SELECT F_GUID() posuuid /*主键*/, INFO.PROD_ID prodid,/*产品代码*/ INFO.ORG_CODE orgCode,/*产品所属机构代码*/ #{reportStartDate,jdbcType=DATE} startdate,/*报表开始日期*/ #{reportEndDate,jdbcType=DATE} enddate,/*报表结束日期*/ #{batchDate,jdbcType=DATE} bookdate,/*统计日期*/ (case INFO.IS_CONSTRACTE when 'Y' then '01' else '02' end) isConstracte,/*是否分级产品*/ INFO.PRODTYPE prodType,/*产品标识*/ INFO.IS_MARKET_FUND isMarketFund,/*货币市场基金*/ INFO.TRANSFER_TYPE transferType,/*转让类型*/ INFO.OPERATE_MODE operateMode,/*运行方式*/ INFO.RAISE_TYPE raisemode,/*募集方式*/ INFO.IVSTORIENTATION ivstorientation,/*投资性质*/ INFO.MANAGE_TYPE manageType,/*管理方式*/ INFO.FIDUCIARY_DUTY fiduciaryDuty,/*受托职责*/ INFO.VDATE,/*起息日*/ (case OPERATE_MODE when '03' then '0' when '04' then '0' else INFO.MDATE - INFO.VDATE end) TERM,/*合同期限*/ CASE WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND NOT EXISTS (SELECT 1 FROM CHB_PRD_DEAL TMP WHERE ifnull(TMP.FPROD_ID,TMP.PROD_ID) = ifnull(D.FPROD_ID,D.PROD_ID) AND TMP.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND TMP.TRADE_TYPE = '16')),0) > 0 THEN '01' WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16'),0) > 0 THEN '02' WHEN ifnull((SELECT count(1) FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE}),0) = 0 THEN '03' ELSE NULL END DURATIONFLAG,/*存续状态*/ DEAL.BUY_PLACE buyPlace,/*销售区域*/ CASE WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) = (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '01' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) > (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '02' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) < (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '03' WHEN ifnull(INFO.TERMINATEDATE,INFO.MDATE) BETWEEN #{reportStartDate,jdbcType=DATE} and #{reportEndDate,jdbcType=DATE} AND NOT EXISTS (SELECT SETTDATE_DATE FROM CHB_PRD_DEAL D WHERE ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.TRADE_TYPE = '16' AND 1 = 1 limit 1) THEN '04' ELSE NULL END PAYSTATUS,/*兑付状态*/ DEAL.CCY,/*币种*/ DEAL.CUSTOMER_TYPE2 customerType2,/*客户二级类型*/ CASE WHEN INFO.PRODTYPE = 'N' THEN DEAL.QM_PRINCE * ifnull((SELECT PROD_VALUE FROM (SELECT RANK() OVER(PARTITION BY PROD_ID ORDER BY CHANGE_DATE DESC) MY_RANK,FPROD_ID,PROD_ID,PROD_VALUE FROM CHB_PRD_PERIODYIELD WHERE CHANGE_DATE <= #{reportEndDate,jdbcType=DATE} AND CHANG_TYPE='01' ) WHERE 1=1 AND ifnull(FPROD_ID,PROD_ID) = INFO.PROD_ID limit 1 ) ,1) ELSE DEAL.QM_PRINCE END ENDAMTSUM_OTH,/*期末余额*/ DEAL.MJ_PRINCE DIRTYAMTSUM,/*募集金额*/ DEAL.DF_PRINCE REDAMT,/*兑付金额*/ DEAL.QM_PRINCE ENDQTYSUM,/*剩余份额*/ CASE WHEN INFO.OPERATE_MODE IN ('01','02') THEN GREATEST(INFO.MDATE - #{reportEndDate,jdbcType=DATE},0) ELSE ( CASE WHEN (SELECT count(1) FROM CHB_PRD_OPENSCH CSCH WHERE CSCH.PROD_ID = INFO.PROD_ID)=0 THEN 1 ELSE GREATEST( ifnull((SELECT MIN(SCH.OPEN_START) FROM CHB_PRD_OPENSCH SCH WHERE SCH.PROD_ID = INFO.PROD_ID AND SCH.OPEN_START > #{reportEndDate,jdbcType=DATE} ) ,INFO.MDATE) - #{reportEndDate,jdbcType=DATE} ,0) END ) END END_DAYS/*剩余期限*/ FROM CHB_PRD_BASEINFO INFO
LEFT JOIN ( SELECT PROD_ID, CCY, CUSTOMER_TYPE2, BUY_PLACE, SUM(MJ_PRINCE) MJ_PRINCE, SUM(DF_PRINCE) DF_PRINCE, SUM(QM_PRINCE) QM_PRINCE FROM ( SELECT ifnull(DL.FPROD_ID,DL.PROD_ID) PROD_ID, CCY, CUSTOMER_TYPE2, BUY_PLACE, DL.SETTDATE_DATE, CASE WHEN DL.SETTDATE_DATE BETWEEN #{reportStartDate,jdbcType=DATE} AND #{reportEndDate,jdbcType=DATE} THEN SUM(CASE WHEN DL.trade_type IN('01','02','05') THEN DL.TRADE_PRINCE ELSE 0 END ) ELSE 0 END MJ_PRINCE, CASE WHEN DL.SETTDATE_DATE BETWEEN #{reportStartDate,jdbcType=DATE} AND #{reportEndDate,jdbcType=DATE} THEN SUM(CASE WHEN DL.trade_type IN('03','16','17') THEN DL.TRADE_PRINCE ELSE 0 END ) ELSE 0 END DF_PRINCE, SUM( case when DL.TRADE_TYPE in ('01','02','05','14') then DL.TRADE_QTY else -1 * DL.TRADE_QTY end ) QM_PRINCE FROM CHB_PRD_DEAL DL WHERE DL.SETTDATE_DATE <= #{reportEndDate,jdbcType=DATE} AND DL.TRADE_TYPE != '04'
AND ifnull(DL.FPROD_ID,DL.PROD_ID) IN
#{prodid,jdbcType=VARCHAR}
/*历史到期产品不统计*/ AND NOT EXISTS(SELECT 1 FROM CHB_PRD_DEAL D WHERE D.TRADE_TYPE = '16' AND ifnull(D.FPROD_ID,D.PROD_ID) = ifnull(DL.FPROD_ID,DL.PROD_ID) AND D.SETTDATE_DATE < #{reportStartDate,jdbcType=DATE}) GROUP BY ifnull(DL.FPROD_ID,DL.PROD_ID),CCY,CUSTOMER_TYPE2,BUY_PLACE,DL.SETTDATE_DATE ) GROUP BY PROD_ID,CCY,CUSTOMER_TYPE2,BUY_PLACE )DEAL ON DEAL.PROD_ID = INFO.PROD_ID
WHERE INFO.FPROD_ID IS NULL /*非保本*/ AND INFO.PROFIT_TYPE = '03'
AND INFO.PROD_ID IN
#{prodid,jdbcType=VARCHAR}
AND INFO.VDATE <= #{reportEndDate,jdbcType=DATE} /*历史到期产品不统计*/ AND NOT EXISTS(SELECT 1 FROM CHB_PRD_DEAL D WHERE D.TRADE_TYPE = '16' AND ifnull(D.FPROD_ID,D.PROD_ID) = INFO.PROD_ID AND D.SETTDATE_DATE < #{reportStartDate,jdbcType=DATE})

select * from PBC_MONTH_PRD_POSITION b inner join chb_prd_baseinfo info on b.prodid = info.prod_id
	where DATE_FORMAT(b.ENDDATE,'%Y-%m-%d') = #{bookDate,jdbcType=VARCHAR}
	and info.profit_type = '03' /*过滤非保本产品*/
